const Map<String, Map<String, String>> dashaBhuktiPhalasExpanded = {
  'ರವಿ': {
    'ರವಿ': 'ರವಿ ಮಹಾದಶೆಯಲ್ಲಿ ರವಿ ಭುಕ್ತಿಯು ಅಧಿಕಾರ ಮತ್ತು ಸರ್ಕಾರಿ ಅನುಕೂಲವನ್ನು ತರುತ್ತದೆ. ವೃತ್ತಿಯಲ್ಲಿ ಉನ್ನತಿ, ಮೇಲಧಿಕಾರಿಗಳ ಮೆಚ್ಚುಗೆ ಮತ್ತು ನಾಯಕತ್ವದ ಅವಕಾಶಗಳು ದೊರೆಯುತ್ತವೆ. ಆರೋಗ್ಯದಲ್ಲಿ ತಲೆನೋವು, ಜ್ವರ, ಪಿತ್ತ ದೋಷ ಮತ್ತು ಕಣ್ಣಿನ ಸಮಸ್ಯೆಗಳು ಕಾಣಿಸಬಹುದು. ತಂದೆಯೊಂದಿಗೆ ಸಂಬಂಧ ಉತ್ತಮವಾಗಿರುತ್ತದೆ, ಆದರೆ ಅಹಂಕಾರ ಹೆಚ್ಚಾಗಬಹುದು.',
    'ಚಂದ್ರ': 'ರವಿ-ಚಂದ್ರ ಭುಕ್ತಿಯಲ್ಲಿ ಶತ್ರುನಾಶ, ಮನಸ್ಸಿಗೆ ನೆಮ್ಮದಿ ಮತ್ತು ಕೀರ್ತಿ ಪ್ರಾಪ್ತಿಯಾಗುತ್ತದೆ. ತಾಯಿ ಅಥವಾ ಸ್ತ್ರೀಯರಿಂದ ಲಾಭ, ವಸ್ತ್ರ-ಆಭರಣ ಪ್ರಾಪ್ತಿ, ಗೃಹ ಸುಖ ಒದಗಿಬರುತ್ತದೆ. ಆರೋಗ್ಯ ಸಾಮಾನ್ಯವಾಗಿ ಉತ್ತಮವಾಗಿರುತ್ತದೆ, ಆದರೆ ಶೀತ-ಕಫ ದೋಷ ಉಂಟಾಗಬಹುದು. ಕುಟುಂಬದಲ್ಲಿ ಶಾಂತಿ ಮತ್ತು ಸಾಮರಸ್ಯ ನೆಲೆಸುತ್ತದೆ.',
    'ಕುಜ': 'ರವಿ-ಕುಜ ಭುಕ್ತಿಯಲ್ಲಿ ಧೈರ್ಯ ಮತ್ತು ಪರಾಕ್ರಮ ವೃದ್ಧಿಯಾಗುತ್ತದೆ. ರೋಗ-ವ್ಯಾಜ್ಯಗಳ ನಿರ್ಮೂಲನೆ, ಅಧಿಕಾರ ಲಾಭ ಮತ್ತು ಸ್ಪರ್ಧೆಗಳಲ್ಲಿ ಜಯ ಸಿಗುತ್ತದೆ. ಆದರೆ ಉಷ್ಣ ರೋಗ, ರಕ್ತ ಸಂಬಂಧಿ ಸಮಸ್ಯೆ ಮತ್ತು ಅಪಘಾತದ ಭಯವಿರುತ್ತದೆ. ಸಹೋದರರೊಂದಿಗೆ ಸಂಬಂಧ ಮಿಶ್ರವಾಗಿರುತ್ತದೆ, ಭೂಮಿ-ವಾಹನ ಲಾಭ ಸಾಧ್ಯ.',
    'ರಾಹು': 'ರವಿ-ರಾಹು ಭುಕ್ತಿಯಲ್ಲಿ ಗ್ರಹಣ ದೋಷದಂತಹ ಅನುಭವವಾಗುತ್ತದೆ. ಸರ್ಕಾರಿ ಅಥವಾ ಮೇಲಧಿಕಾರಿಗಳಿಂದ ಭಯ, ಸ್ಥಾನಪಲ್ಲಟ, ಕಳ್ಳರ ಭಯ ಮತ್ತು ಮಾನಸಿಕ ಗೊಂದಲ ಉಂಟಾಗುತ್ತದೆ. ಅನಿರೀಕ್ಷಿತ ಆರೋಗ್ಯ ಸಮಸ್ಯೆ ಮತ್ತು ವಿಷ ಭಯವಿರುತ್ತದೆ. ಕುಟುಂಬದಲ್ಲಿ ಅಶಾಂತಿ, ತಂದೆಗೆ ಕಷ್ಟ ಮತ್ತು ಅಪಕೀರ್ತಿಯ ಸಾಧ್ಯತೆ ಇರುತ್ತದೆ.',
    'ಗುರು': 'ರವಿ-ಗುರು ಭುಕ್ತಿಯು ಅತ್ಯಂತ ಶುಭಕರವಾಗಿರುತ್ತದೆ. ದೈವಭಕ್ತಿ, ತೀರ್ಥಯಾತ್ರೆ, ವಿದ್ಯೆಯಲ್ಲಿ ಜಯ, ಪುತ್ರಲಾಭ ಮತ್ತು ಯಶಸ್ಸು ಲಭಿಸುತ್ತದೆ. ಆರ್ಥಿಕ ಸ್ಥಿತಿ ಉತ್ತಮವಾಗಿರುತ್ತದೆ, ಗುರುಹಿರಿಯರ ಆಶೀರ್ವಾದ ದೊರೆಯುತ್ತದೆ. ಆರೋಗ್ಯ ಉತ್ತಮ, ಸಮಾಜದಲ್ಲಿ ಗೌರವ ಮತ್ತು ಕೀರ್ತಿ ಹೆಚ್ಚುತ್ತದೆ.',
    'ಶನಿ': 'ರವಿ-ಶನಿ ಭುಕ್ತಿಯಲ್ಲಿ ಕೆಲಸದಲ್ಲಿ ಅಡೆತಡೆ ಮತ್ತು ವಿಳಂಬ ಉಂಟಾಗುತ್ತದೆ. ರೋಗ ಬಾಧೆ, ಕೀಲುನೋವು, ವಾತ ದೋಷ ಮತ್ತು ದೀರ್ಘಕಾಲದ ಕಾಯಿಲೆಗಳ ಸಾಧ್ಯತೆ ಇರುತ್ತದೆ. ತಂದೆಗೆ ಕಷ್ಟ, ಮೇಲಧಿಕಾರಿಗಳೊಂದಿಗೆ ಸಂಘರ್ಷ ಎದುರಾಗಬಹುದು. ಧನಹಾನಿ ಮತ್ತು ಮಾನಸಿಕ ಒತ್ತಡ ಹೆಚ್ಚಾಗುತ್ತದೆ.',
    'ಬುಧ': 'ರವಿ-ಬುಧ ಭುಕ್ತಿಯಲ್ಲಿ ಬುದ್ಧಿಮತ್ತೆ ಮತ್ತು ವಾಕ್‌ಚಾತುರ್ಯದಿಂದ ಯಶಸ್ಸು ಲಭಿಸುತ್ತದೆ. ವ್ಯಾಪಾರ-ವ್ಯವಹಾರದಲ್ಲಿ ಲಾಭ, ಶಿಕ್ಷಣದಲ್ಲಿ ಪ್ರಗತಿ ಮತ್ತು ಸಂವಹನ ಕೌಶಲ ವೃದ್ಧಿಯಾಗುತ್ತದೆ. ಆರೋಗ್ಯ ಸಾಮಾನ್ಯವಾಗಿ ಉತ್ತಮ, ಆದರೆ ನರ ದೌರ್ಬಲ್ಯ ಸಾಧ್ಯ. ಮಿತ್ರರ ಸಮಾಗಮ ಮತ್ತು ಬಂಧುಗಳೊಂದಿಗೆ ಸಂಬಂಧ ಸುಧಾರಿಸುತ್ತದೆ.',
    'ಕೇತು': 'ರವಿ-ಕೇತು ಭುಕ್ತಿಯಲ್ಲಿ ಮನಸ್ಸಿನಲ್ಲಿ ಆತಂಕ ಮತ್ತು ಅನಿಶ್ಚಿತತೆ ಕಾಡುತ್ತದೆ. ಶತ್ರುಗಳಿಂದ ಕಿರುಕುಳ, ವಾಹನದಿಂದ ಎಚ್ಚರ ಮತ್ತು ಗುಪ್ತ ರೋಗಗಳ ಸಾಧ್ಯತೆ ಇರುತ್ತದೆ. ಆಧ್ಯಾತ್ಮಿಕ ಒಲವು ಹೆಚ್ಚಾಗಬಹುದು, ವೈರಾಗ್ಯ ಭಾವನೆ ಉಂಟಾಗುತ್ತದೆ. ತಂದೆಗೆ ಅನಾರೋಗ್ಯ ಅಥವಾ ಸರ್ಕಾರದಿಂದ ದಂಡನೆಯ ಭಯವಿರುತ್ತದೆ.',
    'ಶುಕ್ರ': 'ರವಿ-ಶುಕ್ರ ಭುಕ್ತಿಯಲ್ಲಿ ಸ್ತ್ರೀಯರಿಂದ ಅಥವಾ ಕಲೆಗಳಿಂದ ಲಾಭ ಉಂಟಾಗುತ್ತದೆ. ಮಧುರ ಭೋಜನ, ವಾಹನ ಸುಖ, ವಸ್ತ್ರ-ಆಭರಣ ಪ್ರಾಪ್ತಿಯಾಗುತ್ತದೆ. ದಾಂಪತ್ಯ ಜೀವನದಲ್ಲಿ ಸುಖ ಮತ್ತು ಸಾಮರಸ್ಯ ನೆಲೆಸುತ್ತದೆ. ಆದರೆ ಕಣ್ಣಿನ ಸಮಸ್ಯೆ ಮತ್ತು ಅತಿಯಾದ ವಿಲಾಸದಿಂದ ಆರ್ಥಿಕ ನಷ್ಟ ಸಾಧ್ಯ.',
  },
  'ಚಂದ್ರ': {
    'ಚಂದ್ರ': 'ಚಂದ್ರ-ಚಂದ್ರ ಭುಕ್ತಿಯಲ್ಲಿ ಮನಸ್ಸಿಗೆ ಅಪಾರ ಆನಂದ ಮತ್ತು ಶಾಂತಿ ದೊರೆಯುತ್ತದೆ. ಸುಖ ಭೋಜನ, ಆಭರಣ-ವಸ್ತ್ರ ಲಾಭ, ತಾಯಿಯ ಆಶೀರ್ವಾದ ಪ್ರಾಪ್ತಿಯಾಗುತ್ತದೆ. ಸೃಜನಶೀಲ ಕಾರ್ಯಗಳಲ್ಲಿ ಯಶಸ್ಸು, ಜಲ ಸಂಬಂಧಿ ವ್ಯಾಪಾರದಲ್ಲಿ ಲಾಭ ಸಿಗುತ್ತದೆ. ಕುಟುಂಬದಲ್ಲಿ ಸಂತೋಷ ಮತ್ತು ಸಾಮಾಜಿಕ ಗೌರವ ಹೆಚ್ಚುತ್ತದೆ.',
    'ಕುಜ': 'ಚಂದ್ರ-ಕುಜ ಭುಕ್ತಿಯಲ್ಲಿ ಚಂದ್ರ-ಮಂಗಳ ಯೋಗದ ಪ್ರಭಾವ ಕಂಡುಬರುತ್ತದೆ. ಆರ್ಥಿಕ ಉನ್ನತಿ, ಭೂಮಿ-ವಾಹನ-ಮನೆ ಲಾಭ ಮತ್ತು ಆಸ್ತಿ ವಿಚಾರದಲ್ಲಿ ಅನುಕೂಲವಿರುತ್ತದೆ. ಆದರೆ ಮನಸ್ಸು ಚಂಚಲ, ರಕ್ತ ಸಂಬಂಧಿ ಸಮಸ್ಯೆ ಮತ್ತು ಕೋಪ ಹೆಚ್ಚಾಗಬಹುದು. ಶತ್ರುಗಳ ಮೇಲೆ ಜಯ ಸಿಗುತ್ತದೆ.',
    'ರಾಹು': 'ಚಂದ್ರ-ರಾಹು ಭುಕ್ತಿಯಲ್ಲಿ ಗ್ರಹಣ ದೋಷದಿಂದ ಮಾನಸಿಕ ಆತಂಕ ಹೆಚ್ಚಾಗುತ್ತದೆ. ಜಲಗಂಡ, ವಿಷದ ಭಯ, ವೃಥಾ ಅಪವಾದಗಳು ಮತ್ತು ನಿದ್ರಾಹೀನತೆ ಕಾಡುತ್ತದೆ. ತಾಯಿಗೆ ಸಂಕಷ್ಟ ಅಥವಾ ಅನಾರೋಗ್ಯ ಉಂಟಾಗಬಹುದು. ಮನಸ್ಸಿನ ಅಸ್ಥಿರತೆ, ಭ್ರಮೆ ಮತ್ತು ಅನಗತ್ಯ ಭಯ ಕಾಡುತ್ತದೆ.',
    'ಗುರು': 'ಚಂದ್ರ-ಗುರು ಭುಕ್ತಿಯಲ್ಲಿ ಗಜಕೇಸರಿ ಯೋಗದ ಫಲ ದೊರೆಯುತ್ತದೆ. ಅಖಂಡ ಸಂಪತ್ತು, ಮನಶ್ಯಾಂತಿ, ಸತ್ಕಾರ್ಯ, ಧನಾಗಮ ಮತ್ತು ಪುತ್ರ ಸುಖ ಲಭಿಸುತ್ತದೆ. ವಿದ್ಯೆಯಲ್ಲಿ ಯಶಸ್ಸು, ಗೃಹ-ವಾಹನ ಸುಖ ಮತ್ತು ತೀರ್ಥಯಾತ್ರೆಯ ಯೋಗವಿರುತ್ತದೆ. ಸಮಾಜದಲ್ಲಿ ಅಪಾರ ಗೌರವ ಮತ್ತು ಕೀರ್ತಿ ಪ್ರಾಪ್ತಿಯಾಗುತ್ತದೆ.',
    'ಶನಿ': 'ಚಂದ್ರ-ಶನಿ ಭುಕ್ತಿಯಲ್ಲಿ ಸಾಡೇಸಾತಿಯಂತಹ ಅನುಭವವಾಗುತ್ತದೆ. ವಿಪರೀತ ದುಃಖ, ತೀವ್ರ ಖಿನ್ನತೆ, ನಿದ್ರಾಹೀನತೆ ಮತ್ತು ಮಾನಸಿಕ ಕ್ಲೇಶ ಕಾಡುತ್ತದೆ. ತಾಯಿಗೆ ಕಷ್ಟ, ಆರೋಗ್ಯದಲ್ಲಿ ವಾತ-ಕಫ ದೋಷ ಮತ್ತು ಧನಹಾನಿ ಉಂಟಾಗಬಹುದು. ಕೆಲಸದಲ್ಲಿ ವಿಳಂಬ ಮತ್ತು ಒಂಟಿತನದ ಅನುಭವ ಆಗುತ್ತದೆ.',
    'ಬುಧ': 'ಚಂದ್ರ-ಬುಧ ಭುಕ್ತಿಯಲ್ಲಿ ಮಿತ್ರರ ಸಮಾಗಮ, ಉತ್ತಮ ಕೀರ್ತಿ ಮತ್ತು ವಾಕ್ ಸಿದ್ಧಿ ಲಭಿಸುತ್ತದೆ. ವ್ಯಾಪಾರದಲ್ಲಿ ಲಾಭ, ಬರವಣಿಗೆ-ಮಾಧ್ಯಮದಲ್ಲಿ ಯಶಸ್ಸು ಮತ್ತು ಬುದ್ಧಿ ಚಾತುರ್ಯ ವೃದ್ಧಿಯಾಗುತ್ತದೆ. ಆರೋಗ್ಯ ಉತ್ತಮ, ಮನಸ್ಸಿಗೆ ಉಲ್ಲಾಸ ಮತ್ತು ಸಂತೋಷ ನೆಲೆಸುತ್ತದೆ. ಕುಟುಂಬದಲ್ಲಿ ಸಾಮರಸ್ಯ ಮತ್ತು ಬಂಧುಗಳಿಂದ ಸಹಾಯ ದೊರೆಯುತ್ತದೆ.',
    'ಕೇತು': 'ಚಂದ್ರ-ಕೇತು ಭುಕ್ತಿಯಲ್ಲಿ ಮನಸ್ಸಿನ ಅಸ್ಥಿರತೆ ಮತ್ತು ತೀವ್ರ ಆತಂಕ ಕಾಡುತ್ತದೆ. ಧನಹಾನಿ, ಬೆಂಕಿ-ಅಪಘಾತದ ಭಯ ಮತ್ತು ಅನಿರೀಕ್ಷಿತ ದೋಷಗಳು ಎದುರಾಗಬಹುದು. ತಾಯಿಗೆ ರೋಗ ಅಥವಾ ಜಲ ಭಯ ಉಂಟಾಗಬಹುದು. ಆಧ್ಯಾತ್ಮಿಕ ಸಾಧನೆಗೆ ಒಳ್ಳೆಯ ಕಾಲ, ಆದರೆ ಲೌಕಿಕ ಸುಖದಲ್ಲಿ ಕೊರತೆ.',
    'ಶುಕ್ರ': 'ಚಂದ್ರ-ಶುಕ್ರ ಭುಕ್ತಿಯಲ್ಲಿ ಸುಖ ಭೋಗ, ವಿವಾಹ ಯೋಗ ಮತ್ತು ಕಲಾತ್ಮಕ ಸಾಧನೆ ಲಭಿಸುತ್ತದೆ. ವಾಹನ, ಆಭರಣ ಲಾಭ, ಮಧುರ ಭೋಜನ ಮತ್ತು ಸಂಗೀತ-ಕಲೆಗಳಲ್ಲಿ ಆಸಕ್ತಿ ಹೆಚ್ಚುತ್ತದೆ. ದಾಂಪತ್ಯ ಸುಖ ಮತ್ತು ಸ್ತ್ರೀಯರೊಡನೆ ಉತ್ತಮ ಸಂಬಂಧ ನೆಲೆಸುತ್ತದೆ. ಆರೋಗ್ಯ ಉತ್ತಮ, ಆರ್ಥಿಕ ಸ್ಥಿತಿ ಸುಧಾರಿಸುತ್ತದೆ.',
    'ರವಿ': 'ಚಂದ್ರ-ರವಿ ಭುಕ್ತಿಯಲ್ಲಿ ರಾಜ ಸನ್ಮಾನ, ತಂದೆಯಿಂದ ಲಾಭ ಮತ್ತು ಶತ್ರು ನಾಶ ಉಂಟಾಗುತ್ತದೆ. ಸರ್ಕಾರಿ ಕೆಲಸದಲ್ಲಿ ಅನುಕೂಲ, ಕಣ್ಣಿನ ಆರೋಗ್ಯದಲ್ಲಿ ಸುಧಾರಣೆ ಮತ್ತು ಆತ್ಮವಿಶ್ವಾಸ ವೃದ್ಧಿಯಾಗುತ್ತದೆ. ಸಮಾಜದಲ್ಲಿ ಕೀರ್ತಿ ಮತ್ತು ಗೌರವ ಹೆಚ್ಚುತ್ತದೆ. ಧಾರ್ಮಿಕ ಕಾರ್ಯಗಳಲ್ಲಿ ಆಸಕ್ತಿ ಬೆಳೆಯುತ್ತದೆ.',
  },
  'ಕುಜ': {
    'ಕುಜ': 'ಕುಜ-ಕುಜ ಭುಕ್ತಿಯಲ್ಲಿ ಅಸಾಧಾರಣ ಧೈರ್ಯ ಮತ್ತು ಶಕ್ತಿ ವೃದ್ಧಿಯಾಗುತ್ತದೆ. ಭೂಮಿ-ವಾಹನ ಲಾಭ, ಸ್ಪರ್ಧೆಗಳಲ್ಲಿ ಜಯ ಮತ್ತು ಸೇನಾ-ಪೊಲೀಸ್ ಕ್ಷೇತ್ರದಲ್ಲಿ ಅನುಕೂಲವಿರುತ್ತದೆ. ಆದರೆ ಉಷ್ಣ-ರಕ್ತದ ದೋಷ, ಅಪಘಾತ ಭಯ ಮತ್ತು ಶಸ್ತ್ರಚಿಕಿತ್ಸೆಯ ಸಾಧ್ಯತೆ ಇರುತ್ತದೆ. ಸಹೋದರರೊಂದಿಗೆ ಕಲಹ ಮತ್ತು ಕೋಪದಿಂದ ನಷ್ಟ ಸಂಭವಿಸಬಹುದು.',
    'ರಾಹು': 'ಕುಜ-ರಾಹು ಭುಕ್ತಿಯಲ್ಲಿ ಶಸ್ತ್ರಚಿಕಿತ್ಸೆ, ವಿಷದ ಭಯ ಮತ್ತು ಸ್ಥಾನಚ್ಯುತಿ ಉಂಟಾಗಬಹುದು. ದುಷ್ಟರ ಸಹವಾಸದಿಂದ ಕಷ್ಟ, ಅನಿರೀಕ್ಷಿತ ಅಪಾಯಗಳು ಮತ್ತು ಕಾನೂನು ಸಮಸ್ಯೆಗಳು ಎದುರಾಗಬಹುದು. ಆರೋಗ್ಯದಲ್ಲಿ ರಕ್ತ ಸಂಬಂಧಿ ರೋಗ ಮತ್ತು ನಿಗೂಢ ಕಾಯಿಲೆಗಳ ಸಾಧ್ಯತೆ. ಕುಟುಂಬದಲ್ಲಿ ಅಶಾಂತಿ ಮತ್ತು ಸಹೋದರರಿಗೆ ವಿಪತ್ತು ಬರಬಹುದು.',
    'ಗುರು': 'ಕುಜ-ಗುರು ಭುಕ್ತಿಯಲ್ಲಿ ಗುರುಮಂಗಳ ಯೋಗದ ಶುಭ ಫಲ ದೊರೆಯುತ್ತದೆ. ಜ್ಞಾನ ವೃದ್ಧಿ, ಯಜ್ಞ-ಯಾಗಾದಿಗಳಲ್ಲಿ ಭಾಗಿ, ಸಂಪತ್ತು ಲಾಭ ಮತ್ತು ಧಾರ್ಮಿಕ ಕಾರ್ಯಗಳಲ್ಲಿ ಆಸಕ್ತಿ ಹೆಚ್ಚುತ್ತದೆ. ಆರೋಗ್ಯ ಉತ್ತಮ, ಭೂಮಿ ಲಾಭ ಮತ್ತು ಶತ್ರುಗಳ ಮೇಲೆ ಜಯ ಸಿಗುತ್ತದೆ. ಪುತ್ರ ಸಂತಾನ ಮತ್ತು ಗುರುಹಿರಿಯರ ಆಶೀರ್ವಾದ ದೊರೆಯುತ್ತದೆ.',
    'ಶನಿ': 'ಕುಜ-ಶನಿ ಭುಕ್ತಿಯಲ್ಲಿ ತೀವ್ರ ಕಷ್ಟಕರ ಅನುಭವಗಳಾಗುತ್ತವೆ. ಕಾಯಿಲೆ, ಅಪಘಾತ, ವಾಹನ ನಷ್ಟ ಮತ್ತು ಅನ್ಯರೊಂದಿಗೆ ನಿರಂತರ ಜಗಳ ಉಂಟಾಗುತ್ತದೆ. ವಾತ-ರಕ್ತ ಪ್ರಕೋಪ, ಕೀಲು ನೋವು ಮತ್ತು ಮೂಳೆ ಸಂಬಂಧಿ ಸಮಸ್ಯೆಗಳ ಸಾಧ್ಯತೆ. ಕೆಲಸದಲ್ಲಿ ಅಡೆತಡೆ, ಆರ್ಥಿಕ ನಷ್ಟ ಮತ್ತು ಸಹೋದರರೊಂದಿಗೆ ತೀವ್ರ ವಿವಾದ.',
    'ಬುಧ': 'ಕುಜ-ಬುಧ ಭುಕ್ತಿಯಲ್ಲಿ ಬುದ್ಧಿ-ಧೈರ್ಯದ ಮಿಶ್ರ ಫಲ ಉಂಟಾಗುತ್ತದೆ. ಶತ್ರುನಾಶ, ವ್ಯಾಪಾರದಲ್ಲಿ ಜಾಗರೂಕತೆ ಅಗತ್ಯ ಮತ್ತು ಚರ್ಮ-ನರಗಳ ತೊಂದರೆ ಸಾಧ್ಯ. ವಾಕ್ ಚಾತುರ್ಯದಿಂದ ಜಗಳಗಳನ್ನು ಪರಿಹರಿಸಬಹುದು. ಭೂ-ವಿವಾದ ಮತ್ತು ಕಾನೂನು ಸಮಸ್ಯೆಗಳಲ್ಲಿ ಎಚ್ಚರ ಅಗತ್ಯ.',
    'ಕೇತು': 'ಕುಜ-ಕೇತು ಭುಕ್ತಿಯಲ್ಲಿ ಬೆಂಕಿ-ವಿದ್ಯುತ್‌ನಿಂದ ಅಪಾಯದ ಸಾಧ್ಯತೆ ಇರುತ್ತದೆ. ಆಯುಧಗಳಿಂದ ಗಾಯ, ಮನಸ್ತಾಪ ಮತ್ತು ಅನಿರೀಕ್ಷಿತ ಸಮಸ್ಯೆಗಳು ಎದುರಾಗಬಹುದು. ಶತ್ರುಗಳಿಂದ ಕಿರುಕುಳ ಮತ್ತು ಗುಪ್ತ ವೈರಿಗಳ ಕಾಟ ಇರುತ್ತದೆ. ಆಧ್ಯಾತ್ಮಿಕ ಸಾಧನೆಗೆ ಒಳ್ಳೆಯ ಕಾಲ, ಆದರೆ ಲೌಕಿಕ ಜೀವನದಲ್ಲಿ ಕಷ್ಟ.',
    'ಶುಕ್ರ': 'ಕುಜ-ಶುಕ್ರ ಭುಕ್ತಿಯಲ್ಲಿ ವಾಹನ-ವಸ್ತ್ರ ಲಾಭ ಮತ್ತು ಆಸ್ತಿ ಲಾಭ ಸಾಧ್ಯ. ಆದರೆ ಸ್ತ್ರೀಯರೊಡನೆ ವಿವಾದ, ಗುಪ್ತ ರೋಗ ಮತ್ತು ದಾಂಪತ್ಯ ಜೀವನದಲ್ಲಿ ಸಮಸ್ಯೆ ಉಂಟಾಗಬಹುದು. ಕಲಾ ಕ್ಷೇತ್ರದಲ್ಲಿ ಮಿಶ್ರ ಫಲ, ಮೂತ್ರಪಿಂಡ ಸಂಬಂಧಿ ಸಮಸ್ಯೆ ಸಾಧ್ಯ. ಪಾಲುದಾರಿಕೆಯಲ್ಲಿ ಜಗಳ ಮತ್ತು ಆರ್ಥಿಕ ನಷ್ಟ ಸಂಭವಿಸಬಹುದು.',
    'ರವಿ': 'ಕುಜ-ರವಿ ಭುಕ್ತಿಯಲ್ಲಿ ರಾಜ ಮನ್ನಣೆ, ಧೈರ್ಯ ವೃದ್ಧಿ ಮತ್ತು ಸರ್ಕಾರಿ ಅನುಕೂಲ ಲಭಿಸುತ್ತದೆ. ತಂದೆಗೆ ಲಾಭ, ಶತ್ರುಗಳ ಮೇಲೆ ವಿಜಯ ಮತ್ತು ನಾಯಕತ್ವ ಗುಣ ಹೆಚ್ಚುತ್ತದೆ. ಆದರೆ ಪಿತ್ತ-ಉಷ್ಣ ರೋಗ ಮತ್ತು ಜ್ವರ ಬಾಧೆ ಸಾಧ್ಯ. ಸ್ಪರ್ಧಾತ್ಮಕ ಕ್ಷೇತ್ರದಲ್ಲಿ ಯಶಸ್ಸು ಸಿಗುತ್ತದೆ.',
    'ಚಂದ್ರ': 'ಕುಜ-ಚಂದ್ರ ಭುಕ್ತಿಯಲ್ಲಿ ಚಂದ್ರ-ಮಂಗಳ ಯೋಗದ ಪ್ರಭಾವ ಕಂಡುಬರುತ್ತದೆ. ಆರ್ಥಿಕ ಉನ್ನತಿ, ವಾಹನ-ಮನೆ ಲಾಭ ಮತ್ತು ಆಸ್ತಿ ವೃದ್ಧಿ ಸಾಧ್ಯ. ಆದರೆ ಮನಸ್ಸು ಚಂಚಲ, ಕೋಪ ಹೆಚ್ಚಾಗಬಹುದು ಮತ್ತು ರಕ್ತ ಸಂಬಂಧಿ ಸಮಸ್ಯೆ ಸಾಧ್ಯ. ತಾಯಿಯೊಡನೆ ಸಂಬಂಧದಲ್ಲಿ ಮಿಶ್ರ ಅನುಭವ ಆಗುತ್ತದೆ.',
  },
  'ರಾಹು': {
    'ರಾಹು': 'ರಾಹು-ರಾಹು ಭುಕ್ತಿಯಲ್ಲಿ ವಿಪರೀತ ಮಾನಸಿಕ ಗೊಂದಲ ಮತ್ತು ಭ್ರಮೆ ಕಾಡುತ್ತದೆ. ವಿಷದ ಭೀತಿ, ಕಳ್ಳರ ಕಾಟ, ನಿಗೂಢ ರೋಗಗಳು ಮತ್ತು ಸ್ಥಳಾಂತರ ಉಂಟಾಗಬಹುದು. ಕಾನೂನು ಸಮಸ್ಯೆ, ಜೈಲುವಾಸದ ಭಯ ಮತ್ತು ಅಪಕೀರ್ತಿ ಸಾಧ್ಯ. ಕುಟುಂಬದಲ್ಲಿ ಅಶಾಂತಿ ಮತ್ತು ಸಂಬಂಧಗಳಲ್ಲಿ ಮೋಸ ಎದುರಾಗಬಹುದು.',
    'ಗುರು': 'ರಾಹು-ಗುರು ಭುಕ್ತಿಯಲ್ಲಿ ಗುರುಚಾಂಡಾಲ ದೋಷದ ಪ್ರಭಾವ ಕಂಡುಬರುತ್ತದೆ. ಧಾರ್ಮಿಕ ಕಾರ್ಯ, ದಾನ ಮತ್ತು ಸತ್ಕರ್ಮಗಳಲ್ಲಿ ಆಸಕ್ತಿ ಹೆಚ್ಚಾಗುತ್ತದೆ. ಆದರೂ ಮಾನಸಿಕ ಆತಂಕ, ಗುರು-ಹಿರಿಯರೊಂದಿಗೆ ಮತಭೇದ ಸಾಧ್ಯ. ಆರ್ಥಿಕ ಲಾಭ ಇದ್ದರೂ ಅನಿರೀಕ್ಷಿತ ಖರ್ಚುಗಳು ಬರಬಹುದು.',
    'ಶನಿ': 'ರಾಹು-ಶನಿ ಭುಕ್ತಿಯಲ್ಲಿ ಅತ್ಯಂತ ಕಷ್ಟಕರ ಅನುಭವಗಳಾಗುತ್ತವೆ. ವಾತ ರೋಗ, ಸಾಲದ ಬಾಧೆ, ಕೆಲಸದಲ್ಲಿ ಅಡೆತಡೆ ಮತ್ತು ದೀರ್ಘ ಕಾಲದ ಕಷ್ಟ ಎದುರಾಗುತ್ತದೆ. ಮಾನಸಿಕ ಖಿನ್ನತೆ, ಒಂಟಿತನ ಮತ್ತು ಅವಮಾನ ಸಾಧ್ಯ. ಕುಟುಂಬದಿಂದ ದೂರವಾಗಬೇಕಾಗಬಹುದು.',
    'ಬುಧ': 'ರಾಹು-ಬುಧ ಭುಕ್ತಿಯಲ್ಲಿ ಬುದ್ಧಿ ಭ್ರಮಣೆ ಮತ್ತು ಮಾನಸಿಕ ಗೊಂದಲ ಕಾಡುತ್ತದೆ. ಬಂಧುಗಳೊಂದಿಗೆ ವೈರ, ಚರ್ಮ ರೋಗ ಮತ್ತು ನರ ದೌರ್ಬಲ್ಯ ಸಾಧ್ಯ. ಷೇರು-ವ್ಯಾಪಾರದಲ್ಲಿ ಹಠಾತ್ ಏರಿಳಿತ ಮತ್ತು ಆರ್ಥಿಕ ಅಸ್ಥಿರತೆ ಎದುರಾಗಬಹುದು. ವ್ಯಾಪಾರದಲ್ಲಿ ಮೋಸ ಮತ್ತು ವಂಚನೆಯ ಸಾಧ್ಯತೆ ಇರುತ್ತದೆ.',
    'ಕೇತು': 'ರಾಹು-ಕೇತು ಭುಕ್ತಿಯಲ್ಲಿ ಅಗ್ನಿ ಭಯ, ದೈಹಿಕ ಕಷ್ಟ ಮತ್ತು ಗುಪ್ತ ರೋಗಗಳ ಸಾಧ್ಯತೆ ಇರುತ್ತದೆ. ವೈರಾಗ್ಯ ಭಾವನೆ ಹೆಚ್ಚಾಗಿ ಲೌಕಿಕ ಜೀವನದಲ್ಲಿ ಆಸಕ್ತಿ ಕಡಿಮೆಯಾಗುತ್ತದೆ. ಅನಿರೀಕ್ಷಿತ ಪ್ರಯಾಣ, ಸ್ಥಳಾಂತರ ಮತ್ತು ಜೀವನ ಶೈಲಿಯಲ್ಲಿ ಬದಲಾವಣೆ. ಆಧ್ಯಾತ್ಮಿಕ ಸಾಧನೆಗೆ ಒಳ್ಳೆಯ ಕಾಲ.',
    'ಶುಕ್ರ': 'ರಾಹು-ಶುಕ್ರ ಭುಕ್ತಿಯಲ್ಲಿ ವಿಲಾಸಿ ಜೀವನ ಮತ್ತು ಭೋಗ ಸುಖ ಲಭಿಸುತ್ತದೆ. ಆದರೆ ವಿಜಾತೀಯ ಸಂಬಂಧ, ಹಠಾತ್ ದ್ರೋಹ ಮತ್ತು ಆರ್ಥಿಕ ನಷ್ಟ ಸಾಧ್ಯ. ಚರ್ಮ ರೋಗ, ಮೂತ್ರಪಿಂಡ ಸಮಸ್ಯೆ ಮತ್ತು ಮಧುಮೇಹ ಭಯವಿರುತ್ತದೆ. ಕಲಾ-ಮನರಂಜನಾ ಕ್ಷೇತ್ರದಲ್ಲಿ ಅನಿರೀಕ್ಷಿತ ಯಶಸ್ಸು ಸಿಗಬಹುದು.',
    'ರವಿ': 'ರಾಹು-ರವಿ ಭುಕ್ತಿಯಲ್ಲಿ ಗ್ರಹಣ ದೋಷ ಪ್ರಬಲವಾಗಿರುತ್ತದೆ. ಸರ್ಕಾರದಿಂದ ದಂಡ, ತಂದೆಗೆ ಕಷ್ಟ, ಕಣ್ಣಿನ ದೋಷ ಮತ್ತು ಅಪಕೀರ್ತಿ ಸಾಧ್ಯ. ಅಧಿಕಾರ ನಷ್ಟ, ಮೇಲಧಿಕಾರಿಗಳೊಂದಿಗೆ ಸಂಘರ್ಷ ಎದುರಾಗಬಹುದು. ಆರೋಗ್ಯದಲ್ಲಿ ಉಷ್ಣ-ಪಿತ್ತ ದೋಷ ಮತ್ತು ಹೃದಯ ಸಂಬಂಧಿ ಸಮಸ್ಯೆ.',
    'ಚಂದ್ರ': 'ರಾಹು-ಚಂದ್ರ ಭುಕ್ತಿಯಲ್ಲಿ ಗ್ರಹಣ ದೋಷದಿಂದ ಮಾನಸಿಕ ಖಿನ್ನತೆ ತೀವ್ರವಾಗುತ್ತದೆ. ಜಲಗಂಡ, ತಾಯಿಗೆ ಸಂಕಷ್ಟ, ನಿದ್ರಾಹೀನತೆ ಮತ್ತು ಭ್ರಮೆ ಕಾಡುತ್ತದೆ. ಮನಸ್ಸಿನ ಅಸ್ಥಿರತೆ, ಅನಗತ್ಯ ಭಯ ಮತ್ತು ಚಿಂತೆ ಹೆಚ್ಚಾಗುತ್ತದೆ. ಕುಟುಂಬದಲ್ಲಿ ಅಶಾಂತಿ ಮತ್ತು ಸ್ತ್ರೀಯರಿಂದ ಸಮಸ್ಯೆ.',
    'ಕುಜ': 'ರಾಹು-ಕುಜ ಭುಕ್ತಿಯಲ್ಲಿ ಸರ್ಪ-ಬೆಂಕಿ-ಆಯುಧಗಳಿಂದ ಅಪಾಯದ ಸಾಧ್ಯತೆ ಇರುತ್ತದೆ. ಶಸ್ತ್ರಚಿಕಿತ್ಸೆ, ಅಪಘಾತ ಮತ್ತು ರಕ್ತ ಸಂಬಂಧಿ ಸಮಸ್ಯೆಗಳ ಭಯವಿರುತ್ತದೆ. ಸಹೋದರರಿಗೆ ವಿಪತ್ತು ಮತ್ತು ಶತ್ರುಗಳಿಂದ ತೀವ್ರ ಕಿರುಕುಳ. ಕೋಪ ನಿಯಂತ್ರಣ ಅಗತ್ಯ, ಕಾನೂನು ಸಮಸ್ಯೆಗಳಿಂದ ದೂರವಿರಬೇಕು.',
  },
  'ಗುರು': {
    'ಗುರು': 'ಗುರು-ಗುರು ಭುಕ್ತಿಯಲ್ಲಿ ಅತ್ಯಂತ ಶುಭಕರ ಫಲ ದೊರೆಯುತ್ತದೆ. ಸತ್ಕರ್ಮ, ಧನ-ಧಾನ್ಯ ಲಾಭ, ಪುತ್ರ ಸಂತಾನ ಮತ್ತು ರಾಜ ಸನ್ಮಾನ ಪ್ರಾಪ್ತಿಯಾಗುತ್ತದೆ. ತೀರ್ಥಯಾತ್ರೆ, ಧಾರ್ಮಿಕ ಕಾರ್ಯ ಮತ್ತು ವಿದ್ಯೆಯಲ್ಲಿ ಅಪಾರ ಯಶಸ್ಸು ಸಿಗುತ್ತದೆ. ಸಮಾಜದಲ್ಲಿ ಗೌರವ, ಆರೋಗ್ಯ ಉತ್ತಮ ಮತ್ತು ಕುಟುಂಬದಲ್ಲಿ ಸಂತೋಷ.',
    'ಶನಿ': 'ಗುರು-ಶನಿ ಭುಕ್ತಿಯಲ್ಲಿ ಆಲಸ್ಯ, ವಾತ ರೋಗ ಮತ್ತು ಕೆಲಸದಲ್ಲಿ ವಿಳಂಬ ಉಂಟಾಗುತ್ತದೆ. ಹಣಕಾಸಿನ ಮುಗ್ಗಟ್ಟು, ಯಕೃತ್ತಿನ ಸಮಸ್ಯೆ ಮತ್ತು ದೀರ್ಘಕಾಲದ ಕಾಯಿಲೆ ಸಾಧ್ಯ. ಗುರು-ಹಿರಿಯರೊಂದಿಗೆ ಸಂಬಂಧದಲ್ಲಿ ಒತ್ತಡ ಮತ್ತು ಧಾರ್ಮಿಕ ಕಾರ್ಯಗಳಲ್ಲಿ ಅಡೆತಡೆ. ಆದರೂ ಶ್ರಮದಿಂದ ನಿಧಾನ ಪ್ರಗತಿ ಸಾಧ್ಯ.',
    'ಬುಧ': 'ಗುರು-ಬುಧ ಭುಕ್ತಿಯಲ್ಲಿ ಜ್ಞಾನ-ವಿದ್ಯೆ ವೃದ್ಧಿ ಮತ್ತು ಬೌದ್ಧಿಕ ಸಾಧನೆ ಲಭಿಸುತ್ತದೆ. ವ್ಯಾಪಾರ ಲಾಭ, ಜ್ಯೋತಿಷ್ಯ-ವೇದಾಂತದಲ್ಲಿ ಕೀರ್ತಿ ಮತ್ತು ಉನ್ನತ ಶಿಕ್ಷಣದಲ್ಲಿ ಯಶಸ್ಸು ಸಿಗುತ್ತದೆ. ಸಂವಹನ ಕೌಶಲ ವೃದ್ಧಿ ಮತ್ತು ಬರವಣಿಗೆ-ಪ್ರಕಾಶನದಲ್ಲಿ ಅನುಕೂಲ. ಆರೋಗ್ಯ ಉತ್ತಮ, ಮಿತ್ರರ ಸಹಾಯ ದೊರೆಯುತ್ತದೆ.',
    'ಕೇತು': 'ಗುರು-ಕೇತು ಭುಕ್ತಿಯಲ್ಲಿ ಆಧ್ಯಾತ್ಮಿಕ ಪ್ರಗತಿ ಮತ್ತು ಯೋಗ-ಧ್ಯಾನದಲ್ಲಿ ಸಾಧನೆ ಆಗುತ್ತದೆ. ತೀರ್ಥಯಾತ್ರೆ, ಗುಪ್ತ ಶತ್ರುಗಳ ನಾಶ ಮತ್ತು ಮೋಕ್ಷ ಮಾರ್ಗದಲ್ಲಿ ಆಸಕ್ತಿ ಹೆಚ್ಚುತ್ತದೆ. ಲೌಕಿಕ ಸುಖದಲ್ಲಿ ಕೊರತೆ ಇದ್ದರೂ ಆಂತರಿಕ ಶಾಂತಿ ದೊರೆಯುತ್ತದೆ. ಗುಪ್ತ ಸಂಪತ್ತು ಲಾಭ ಸಾಧ್ಯ.',
    'ಶುಕ್ರ': 'ಗುರು-ಶುಕ್ರ ಭುಕ್ತಿಯಲ್ಲಿ ವಸ್ತ್ರ-ಆಭರಣ-ವಾಹನ ಲಾಭ ಮತ್ತು ದಾಂಪತ್ಯ ಸುಖ ಲಭಿಸುತ್ತದೆ. ವಿವಾಹ ಯೋಗ, ಕಲಾ ಕ್ಷೇತ್ರದಲ್ಲಿ ಯಶಸ್ಸು ಮತ್ತು ಸಂಗೀತ-ಸಾಹಿತ್ಯದಲ್ಲಿ ಆಸಕ್ತಿ ಹೆಚ್ಚುತ್ತದೆ. ಆದರೆ ಕಫ-ಪಿತ್ತ ದೋಷ ಮತ್ತು ಹೊಟ್ಟೆ ಸಂಬಂಧಿ ಸಮಸ್ಯೆ ಸಾಧ್ಯ. ಸಾಮಾಜಿಕ ಗೌರವ ಮತ್ತು ಸಂಪತ್ತು ವೃದ್ಧಿಯಾಗುತ್ತದೆ.',
    'ರವಿ': 'ಗುರು-ರವಿ ಭುಕ್ತಿಯಲ್ಲಿ ಶಿವಾಲಯ ದರ್ಶನ, ರಾಜಕೀಯ ಲಾಭ ಮತ್ತು ಆರೋಗ್ಯ ವೃದ್ಧಿ ಲಭಿಸುತ್ತದೆ. ತಂದೆಯಿಂದ ಆಸ್ತಿ, ಸರ್ಕಾರಿ ಗೌರವ ಮತ್ತು ನಾಯಕತ್ವದ ಅವಕಾಶ ದೊರೆಯುತ್ತದೆ. ಧಾರ್ಮಿಕ ಕಾರ್ಯಗಳಲ್ಲಿ ಆಸಕ್ತಿ ಮತ್ತು ಗುರು-ಹಿರಿಯರ ಆಶೀರ್ವಾದ ಪ್ರಾಪ್ತಿ. ಆತ್ಮವಿಶ್ವಾಸ ಮತ್ತು ಕೀರ್ತಿ ಹೆಚ್ಚುತ್ತದೆ.',
    'ಚಂದ್ರ': 'ಗುರು-ಚಂದ್ರ ಭುಕ್ತಿಯಲ್ಲಿ ಗಜಕೇಸರಿ ಯೋಗದ ಅದ್ಭುತ ಫಲ ದೊರೆಯುತ್ತದೆ. ಅಖಂಡ ಸಂಪತ್ತು, ಮನಶ್ಯಾಂತಿ, ಗೃಹ-ವಾಹನ ಸುಖ ಮತ್ತು ಸಮಾಜದಲ್ಲಿ ಅಪಾರ ಗೌರವ ಲಭಿಸುತ್ತದೆ. ತಾಯಿಗೆ ಸುಖ, ಸೃಜನಶೀಲ ಕಾರ್ಯಗಳಲ್ಲಿ ಯಶಸ್ಸು ಮತ್ತು ಆರೋಗ್ಯ ಉತ್ತಮ. ವಿವಾಹ ಯೋಗ ಮತ್ತು ಪುತ್ರ ಸಂತಾನ ಲಾಭ.',
    'ಕುಜ': 'ಗುರು-ಕುಜ ಭುಕ್ತಿಯಲ್ಲಿ ಭೂಲಾಭ, ಶತ್ರುಗಳ ಮೇಲೆ ಜಯ ಮತ್ತು ಅಸಾಧಾರಣ ಧೈರ್ಯ ಲಭಿಸುತ್ತದೆ. ಆಸ್ತಿ ವೃದ್ಧಿ, ವಾಹನ ಲಾಭ ಮತ್ತು ಸ್ಪರ್ಧೆಗಳಲ್ಲಿ ವಿಜಯ ಸಾಧ್ಯ. ಆದರೆ ಉಷ್ಣ ರೋಗ, ಪಿತ್ತ ದೋಷ ಮತ್ತು ಕೋಪ ಹೆಚ್ಚಾಗಬಹುದು. ಧಾರ್ಮಿಕ ಯಜ್ಞ-ಕಾರ್ಯಗಳಲ್ಲಿ ಆಸಕ್ತಿ.',
    'ರಾಹು': 'ಗುರು-ರಾಹು ಭುಕ್ತಿಯಲ್ಲಿ ಚಾಂಡಾಲ ಯೋಗದ ಪ್ರಭಾವ ಕಂಡುಬರುತ್ತದೆ. ಬಂಧು-ಮಿತ್ರರ ವಿರೋಧ, ಧರ್ಮ ಭ್ರಷ್ಟತೆ ಮತ್ತು ಮಾನಸಿಕ ಗೊಂದಲ ಉಂಟಾಗಬಹುದು. ಹೊಟ್ಟೆ-ಯಕೃತ್ತಿನ ಕಾಯಿಲೆ, ಅನಿರೀಕ್ಷಿತ ಖರ್ಚು ಮತ್ತು ಅಪಕೀರ್ತಿ ಸಾಧ್ಯ. ಗುರು-ಹಿರಿಯರೊಂದಿಗೆ ಮತಭೇದ ಮತ್ತು ಧಾರ್ಮಿಕ ಸಂಶಯ.',
  },

  'ಶನಿ': {
    'ಶನಿ': 'ಶನಿ ಮಹಾದಶೆಯಲ್ಲಿ ಶನಿ ಭುಕ್ತಿಯು ಕಠಿಣ ಪರಿಶ್ರಮ ಮತ್ತು ವಿಳಂಬದ ಅನುಭವ ನೀಡುತ್ತದೆ. ವೃತ್ತಿಯಲ್ಲಿ ಸ್ಥಿರತೆ ಬರಬಹುದಾದರೂ, ಪ್ರಗತಿ ನಿಧಾನಗತಿಯಲ್ಲಿರುತ್ತದೆ ಮತ್ತು ಅಡೆತಡೆಗಳು ಕಾಣಿಸಿಕೊಳ್ಳುತ್ತವೆ. ಮೂಳೆ-ಸಂಧಿ ನೋವು, ವಾತ ರೋಗ ಮತ್ತು ದೈಹಿಕ ಬಳಲಿಕೆ ಉಂಟಾಗಬಹುದು. ಕುಟುಂಬದಲ್ಲಿ ಹಿರಿಯರ ಆರೋಗ್ಯ ಕ್ಷೀಣಿಸಬಹುದು, ಸೇವಕರಿಂದ ತೊಂದರೆ ಮತ್ತು ಒಂಟಿತನದ ಅನುಭವ ಸಾಧ್ಯ.',
    'ಬುಧ': 'ಶನಿ-ಬುಧ ಭುಕ್ತಿಯಲ್ಲಿ ಬುದ್ಧಿಶಕ್ತಿಯಿಂದ ಕಷ್ಟಗಳನ್ನು ನಿವಾರಿಸಿಕೊಳ್ಳುವ ಸಾಮರ್ಥ್ಯ ಬರುತ್ತದೆ. ವ್ಯಾಪಾರ-ವಾಣಿಜ್ಯದಲ್ಲಿ ಸುಧಾರಣೆ, ಲೆಕ್ಕ-ಪತ್ರ ಕಾರ್ಯಗಳಲ್ಲಿ ಲಾಭ ಮತ್ತು ಶಿಕ್ಷಣ ಕ್ಷೇತ್ರದಲ್ಲಿ ಪ್ರಗತಿ ಕಾಣಬಹುದು. ಚರ್ಮ ರೋಗ, ನರ ದೌರ್ಬಲ್ಯ ಮತ್ತು ಉಸಿರಾಟ ಸಂಬಂಧಿ ಸಮಸ್ಯೆ ಸಾಧ್ಯ. ಬಂಧು-ಮಿತ್ರರ ಸಹಾಯ ಸಿಗಬಹುದು, ಆದರೆ ವಿವಾದಗಳಲ್ಲಿ ಎಚ್ಚರ ಅಗತ್ಯ.',
    'ಕೇತು': 'ಶನಿ-ಕೇತು ಭುಕ್ತಿಯಲ್ಲಿ ಅನಿರೀಕ್ಷಿತ ಕಷ್ಟಗಳು ಮತ್ತು ಆಧ್ಯಾತ್ಮಿಕ ಒಲವು ಕಂಡುಬರುತ್ತದೆ. ವೃತ್ತಿಯಲ್ಲಿ ಅಸ್ಥಿರತೆ, ಹಠಾತ್ ನಷ್ಟ ಮತ್ತು ಸ್ಥಾನಪಲ್ಲಟ ಸಾಧ್ಯ. ಕಾಲು-ಪಾದ ನೋವು, ಅಸ್ಪಷ್ಟ ರೋಗ ಮತ್ತು ಶಸ್ತ್ರಚಿಕಿತ್ಸೆಯ ಭಯ ಇರುತ್ತದೆ. ಪೂರ್ವಜನ್ಮ ಕರ್ಮಫಲ ಅನುಭವ, ಕುಟುಂಬದಲ್ಲಿ ವಿಚ್ಛೇದ ಮತ್ತು ಧ್ಯಾನ-ಸಾಧನೆಯತ್ತ ಒಲವು.',
    'ಶುಕ್ರ': 'ಶನಿ-ಶುಕ್ರ ಭುಕ್ತಿಯಲ್ಲಿ ಭೋಗ-ಸುಖ ಮತ್ತು ಸಂಪತ್ತಿನ ಲಾಭ ಸಾಧ್ಯ. ವಾಹನ-ಭೂಮಿ ಯೋಗ, ಕಲಾ ಕ್ಷೇತ್ರದಲ್ಲಿ ಯಶಸ್ಸು ಮತ್ತು ವಿವಾಹ ಸಂಬಂಧಿ ಶುಭ ಘಟನೆಗಳು ನಡೆಯಬಹುದು. ಆದರೆ ಜನನೇಂದ್ರಿಯ ಸಮಸ್ಯೆ, ಮಧುಮೇಹ ಮತ್ತು ಕಣ್ಣಿನ ತೊಂದರೆ ಸಾಧ್ಯ. ದಾಂಪತ್ಯದಲ್ಲಿ ಮಿಶ್ರ ಫಲ, ಪತ್ನಿ/ಪತಿಯ ಆರೋಗ್ಯದ ಬಗ್ಗೆ ಎಚ್ಚರ ಅಗತ್ಯ.',
    'ರವಿ': 'ಶನಿ-ರವಿ ಭುಕ್ತಿಯಲ್ಲಿ ಅಧಿಕಾರಿಗಳೊಂದಿಗೆ ಸಂಘರ್ಷ ಮತ್ತು ಸರ್ಕಾರಿ ತೊಂದರೆ ಕಂಡುಬರುತ್ತದೆ. ತಂದೆಯ ಆರೋಗ್ಯ ಕ್ಷೀಣಿಸಬಹುದು, ಆಸ್ತಿ ವಿವಾದ ಮತ್ತು ಸ್ಥಾನಮಾನ ಕಡಿಮೆಯಾಗುವ ಭಯ. ಜ್ವರ-ಉಷ್ಣ ರೋಗ, ಹೃದಯ ಸಂಬಂಧಿ ಸಮಸ್ಯೆ ಮತ್ತು ದೈಹಿಕ ಬಳಲಿಕೆ ಉಂಟಾಗಬಹುದು. ಧೈರ್ಯ-ಆತ್ಮವಿಶ್ವಾಸ ಕಡಿಮೆಯಾಗಿ ಮಾನಸಿಕ ಒತ್ತಡ ಹೆಚ್ಚಾಗುತ್ತದೆ.',
    'ಚಂದ್ರ': 'ಶನಿ-ಚಂದ್ರ ಭುಕ್ತಿಯಲ್ಲಿ ಮನಸ್ಸಿಗೆ ಅಶಾಂತಿ ಮತ್ತು ಭಾವನಾತ್ಮಕ ಕಷ್ಟಗಳು ಉಂಟಾಗುತ್ತವೆ. ತಾಯಿಯ ಆರೋಗ್ಯ ಕ್ಷೀಣ, ಗೃಹ ಸುಖ ಕಡಿಮೆ ಮತ್ತು ಸಾರ್ವಜನಿಕ ಅಪಕೀರ್ತಿ ಸಾಧ್ಯ. ಕಫ-ವಾತ ದೋಷ, ಜಲ ಸಂಬಂಧಿ ರೋಗ ಮತ್ತು ನಿದ್ರಾಹೀನತೆ ಕಾಡಬಹುದು. ದೈನಂದಿನ ಜೀವನದಲ್ಲಿ ಅಡೆತಡೆಗಳು, ಆದರೆ ಸಹನೆಯಿಂದ ಗೆಲ್ಲಬಹುದು.',
    'ಕುಜ': 'ಶನಿ-ಕುಜ ಭುಕ್ತಿಯಲ್ಲಿ ಶತ್ರುಗಳ ಕಿರುಕುಳ, ವ್ಯಾಜ್ಯ ಮತ್ತು ಅಪಘಾತದ ಭಯ ಇರುತ್ತದೆ. ಭೂಮಿ-ಆಸ್ತಿ ವಿವಾದ, ಸಹೋದರರೊಂದಿಗೆ ಮನಸ್ತಾಪ ಮತ್ತು ಶತ್ರುಗಳ ಮೇಲೆ ಸೋಲು ಸಾಧ್ಯ. ರಕ್ತ ದೋಷ, ಮೂಳೆ ಮುರಿತ ಮತ್ತು ಶಸ್ತ್ರಚಿಕಿತ್ಸೆಯ ಅಗತ್ಯ ಬರಬಹುದು. ಕ್ರೋಧ ನಿಯಂತ್ರಣ ಮತ್ತು ಸಂಯಮ ಅಗತ್ಯ.',
    'ರಾಹು': 'ಶನಿ-ರಾಹು ಭುಕ್ತಿಯಲ್ಲಿ ಅತ್ಯಂತ ಕಠಿಣ ಕಾಲ ಅನುಭವವಾಗಬಹುದು. ಅನಿರೀಕ್ಷಿತ ಆಪತ್ತುಗಳು, ಮೋಸ, ವಿದೇಶ ಪ್ರಯಾಣ ಮತ್ತು ಸ್ಥಾನ ಭ್ರಷ್ಟತೆ ಸಾಧ್ಯ. ಅಸ್ಪಷ್ಟ ರೋಗ, ವಿಷ ಭಯ ಮತ್ತು ಮಾನಸಿಕ ಖಿನ್ನತೆ ಕಾಡಬಹುದು. ಕುಟುಂಬದಲ್ಲಿ ಅಶಾಂತಿ, ಕಳ್ಳರ ಭಯ ಮತ್ತು ನಿಂದೆ.',
    'ಗುರು': 'ಶನಿ-ಗುರು ಭುಕ್ತಿಯಲ್ಲಿ ಧಾರ್ಮಿಕ ಕಾರ್ಯಗಳಲ್ಲಿ ಆಸಕ್ತಿ ಮತ್ತು ಗುರು ಕೃಪೆ ಲಭಿಸುತ್ತದೆ. ವಿದ್ಯಾ ಲಾಭ, ಸಂತಾನ ಸುಖ ಮತ್ತು ಧರ್ಮ-ಕರ್ಮಗಳಲ್ಲಿ ಪ್ರಗತಿ ಕಾಣಬಹುದು. ಆರೋಗ್ಯ ಸುಧಾರಿಸುತ್ತದೆ, ಆದರೆ ಕೊಬ್ಬು ಹೆಚ್ಚಾಗುವುದು ಮತ್ತು ಯಕೃತ್ತಿನ ಸಮಸ್ಯೆ ಸಾಧ್ಯ. ಸಮಾಜದಲ್ಲಿ ಗೌರವ ಹೆಚ್ಚುತ್ತದೆ ಮತ್ತು ಸತ್ಕರ್ಮಗಳ ಫಲ ದೊರೆಯುತ್ತದೆ.',
  },
  'ಬುಧ': {
    'ಬುಧ': 'ಬುಧ ಮಹಾದಶೆಯಲ್ಲಿ ಬುಧ ಭುಕ್ತಿಯು ಬುದ್ಧಿಶಕ್ತಿ ಮತ್ತು ವಾಕ್ಚಾತುರ್ಯದ ವೃದ್ಧಿ ನೀಡುತ್ತದೆ. ವ್ಯಾಪಾರ-ವಾಣಿಜ್ಯದಲ್ಲಿ ಲಾಭ, ಶಿಕ್ಷಣ ಕ್ಷೇತ್ರದಲ್ಲಿ ಯಶಸ್ಸು ಮತ್ತು ಲೇಖನ-ಸಂವಹನ ಕಾರ್ಯಗಳಲ್ಲಿ ಪ್ರಗತಿ. ಚರ್ಮ ರೋಗ, ನರ ದೌರ್ಬಲ್ಯ ಮತ್ತು ಉಸಿರಾಟ ಸಮಸ್ಯೆ ಸಾಧ್ಯ. ಮಿತ್ರ-ಬಂಧು ಸಹಕಾರ, ವಿದ್ಯಾರ್ಥಿಗಳಿಗೆ ಶುಭಫಲ ಮತ್ತು ಸಂವಹನ ಕೌಶಲ ವೃದ್ಧಿ.',
    'ಕೇತು': 'ಬುಧ-ಕೇತು ಭುಕ್ತಿಯಲ್ಲಿ ಬುದ್ಧಿಭ್ರಮಣೆ, ಗೊಂದಲ ಮತ್ತು ತಪ್ಪು ನಿರ್ಧಾರಗಳ ಸಾಧ್ಯತೆ ಇರುತ್ತದೆ. ವ್ಯಾಪಾರದಲ್ಲಿ ಮೋಸ, ಶಿಕ್ಷಣದಲ್ಲಿ ಅಡೆತಡೆ ಮತ್ತು ಅನಿರೀಕ್ಷಿತ ನಷ್ಟ ಸಾಧ್ಯ. ಚರ್ಮ-ನರ ರೋಗ, ಅಸ್ಪಷ್ಟ ಕಾಯಿಲೆ ಮತ್ತು ಮಾನಸಿಕ ಚಂಚಲತೆ. ಅಧ್ಯಾತ್ಮಿಕ ಚಿಂತನೆಯ ಕಡೆ ಒಲವು ಹೆಚ್ಚಾಗಬಹುದು.',
    'ಶುಕ್ರ': 'ಬುಧ-ಶುಕ್ರ ಭುಕ್ತಿಯಲ್ಲಿ ಕಲಾ-ಸಾಹಿತ್ಯ-ಸಂಗೀತದಲ್ಲಿ ಯಶಸ್ಸು ಮತ್ತು ಭೋಗ ಸುಖ ಲಭಿಸುತ್ತದೆ. ವ್ಯಾಪಾರದಲ್ಲಿ ಉತ್ತಮ ಲಾಭ, ವಸ್ತ್ರ-ಆಭರಣ ಪ್ರಾಪ್ತಿ ಮತ್ತು ವಿವಾಹ ಯೋಗ ಕಾಣಬಹುದು. ಆರೋಗ್ಯ ಸಾಮಾನ್ಯವಾಗಿ ಉತ್ತಮ, ಆದರೆ ಅತಿ ಭೋಗದಿಂದ ಕಫ ವೃದ್ಧಿ ಸಾಧ್ಯ. ದಾಂಪತ್ಯ ಸುಖ ಮತ್ತು ಸಾಮಾಜಿಕ ಗೌರವ ಹೆಚ್ಚುತ್ತದೆ.',
    'ರವಿ': 'ಬುಧ-ರವಿ ಭುಕ್ತಿಯಲ್ಲಿ ಸರ್ಕಾರಿ ಅನುಕೂಲ, ಅಧಿಕಾರ ಸ್ಥಾನ ಮತ್ತು ವೃತ್ತಿ ಉನ್ನತಿ ಲಭಿಸುತ್ತದೆ. ವ್ಯಾಪಾರ-ವಾಣಿಜ್ಯದಲ್ಲಿ ಸರ್ಕಾರಿ ಗುತ್ತಿಗೆ, ಪ್ರಮೋಷನ್ ಮತ್ತು ನಾಯಕತ್ವದ ಅವಕಾಶ. ತಲೆನೋವು, ಕಣ್ಣಿನ ಸಮಸ್ಯೆ ಮತ್ತು ಪಿತ್ತ ದೋಷ ಸಾಧ್ಯ. ತಂದೆಯೊಂದಿಗೆ ಉತ್ತಮ ಸಂಬಂಧ ಮತ್ತು ಬೌದ್ಧಿಕ ಸಾಧನೆ.',
    'ಚಂದ್ರ': 'ಬುಧ-ಚಂದ್ರ ಭುಕ್ತಿಯಲ್ಲಿ ಕಲ್ಪನಾಶಕ್ತಿ, ಸೃಜನಶೀಲತೆ ಮತ್ತು ಸಂವಹನ ಕೌಶಲ ಹೆಚ್ಚುತ್ತದೆ. ವ್ಯಾಪಾರದಲ್ಲಿ ಸಾರ್ವಜನಿಕ ಸಂಬಂಧ ಲಾಭ, ಲೇಖನ-ಮಾಧ್ಯಮ ಕ್ಷೇತ್ರದಲ್ಲಿ ಯಶಸ್ಸು. ಕಫ-ಶೀತ ರೋಗ ಮತ್ತು ಮನಸ್ಸಿನ ಚಂಚಲತೆ ಸಾಧ್ಯ. ತಾಯಿಯೊಂದಿಗೆ ಉತ್ತಮ ಸಂಬಂಧ, ಗೃಹ ಸುಖ ಮತ್ತು ಭಾವನಾತ್ಮಕ ಸ್ಥಿರತೆ.',
    'ಕುಜ': 'ಬುಧ-ಕುಜ ಭುಕ್ತಿಯಲ್ಲಿ ವಾದ-ವಿವಾದ, ಕಾನೂನು ಸಮಸ್ಯೆ ಮತ್ತು ಶತ್ರುಗಳ ಕಿರುಕುಳ ಸಾಧ್ಯ. ವ್ಯಾಪಾರದಲ್ಲಿ ಅತಿ ಆತುರದ ನಿರ್ಧಾರಗಳಿಂದ ನಷ್ಟ ಬರಬಹುದು. ಚರ್ಮ ರೋಗ, ರಕ್ತ ದೋಷ ಮತ್ತು ಅಪಘಾತದ ಭಯ. ಸಹೋದರರೊಂದಿಗೆ ಮನಸ್ತಾಪ, ಆದರೆ ಧೈರ್ಯ-ಪರಾಕ್ರಮ ಹೆಚ್ಚಾಗುತ್ತದೆ.',
    'ರಾಹು': 'ಬುಧ-ರಾಹು ಭುಕ್ತಿಯಲ್ಲಿ ಮಾನಸಿಕ ಗೊಂದಲ, ಮೋಸ ಮತ್ತು ನಂಬಿಕೆ ದ್ರೋಹ ಅನುಭವವಾಗಬಹುದು. ವ್ಯಾಪಾರದಲ್ಲಿ ಕಳ್ಳತನ, ಶಿಕ್ಷಣದಲ್ಲಿ ಅಡೆತಡೆ ಮತ್ತು ಸಂವಹನದಲ್ಲಿ ತಪ್ಪು ತಿಳುವಳಿಕೆ. ನರ ದೌರ್ಬಲ್ಯ, ಚರ್ಮ ರೋಗ ಮತ್ತು ವಿಷ ಭಯ ಸಾಧ್ಯ. ಬಂಧುಗಳಿಂದ ಮೋಸ ಮತ್ತು ಅಪಕೀರ್ತಿ ಸಾಧ್ಯತೆ.',
    'ಗುರು': 'ಬುಧ-ಗುರು ಭುಕ್ತಿಯಲ್ಲಿ ವಿದ್ಯಾ-ಜ್ಞಾನ ಲಾಭ ಮತ್ತು ಧಾರ್ಮಿಕ ಕಾರ್ಯಗಳಲ್ಲಿ ಪ್ರಗತಿ ಕಾಣಬಹುದು. ಶಿಕ್ಷಣ ಕ್ಷೇತ್ರದಲ್ಲಿ ಉನ್ನತ ಸ್ಥಾನ, ಗುರು ಕೃಪೆ ಮತ್ತು ಧಾರ್ಮಿಕ ಯಾತ್ರೆ ಸಾಧ್ಯ. ಆರೋಗ್ಯ ಸಾಮಾನ್ಯವಾಗಿ ಉತ್ತಮ, ಕೊಬ್ಬು ವೃದ್ಧಿ ಸಾಧ್ಯ. ಸಂತಾನ ಸುಖ, ಸಾಮಾಜಿಕ ಗೌರವ ಮತ್ತು ಬೌದ್ಧಿಕ ಪ್ರಗತಿ.',
    'ಶನಿ': 'ಬುಧ-ಶನಿ ಭುಕ್ತಿಯಲ್ಲಿ ವ್ಯಾಪಾರದಲ್ಲಿ ವಿಳಂಬ ಮತ್ತು ಕಠಿಣ ಪರಿಶ್ರಮದ ಅಗತ್ಯ ಬರುತ್ತದೆ. ಶಿಕ್ಷಣದಲ್ಲಿ ಅಡೆತಡೆ, ಸಂವಹನದಲ್ಲಿ ತೊಂದರೆ ಮತ್ತು ನಿರ್ಧಾರ ತೆಗೆದುಕೊಳ್ಳುವಲ್ಲಿ ವಿಳಂಬ. ವಾತ ರೋಗ, ಮೂಳೆ ನೋವು ಮತ್ತು ನರ ಸಮಸ್ಯೆ ಸಾಧ್ಯ. ಬಂಧುಗಳಿಂದ ದೂರ, ಒಂಟಿತನ ಅನುಭವ ಮತ್ತು ಸಹನೆ ಅಗತ್ಯ.',
  },
  'ಕೇತು': {
    'ಕೇತು': 'ಕೇತು ಮಹಾದಶೆಯಲ್ಲಿ ಕೇತು ಭುಕ್ತಿಯು ಆಧ್ಯಾತ್ಮಿಕ ಜಾಗೃತಿ ಮತ್ತು ಲೌಕಿಕ ವಿರಕ್ತಿ ನೀಡುತ್ತದೆ. ಅನಿರೀಕ್ಷಿತ ಘಟನೆಗಳು, ಹಠಾತ್ ಬದಲಾವಣೆ ಮತ್ತು ಪೂರ್ವಜನ್ಮ ಕರ್ಮಫಲ ಅನುಭವ. ಅಸ್ಪಷ್ಟ ರೋಗ, ಶಸ್ತ್ರಚಿಕಿತ್ಸೆಯ ಅಗತ್ಯ ಮತ್ತು ಅಪಘಾತ ಭಯ. ಕುಟುಂಬದಿಂದ ದೂರ, ಧ್ಯಾನ-ಯೋಗದತ್ತ ಆಕರ್ಷಣೆ ಮತ್ತು ಮೋಕ್ಷ ಮಾರ್ಗದ ಹುಡುಕಾಟ.',
    'ಶುಕ್ರ': 'ಕೇತು-ಶುಕ್ರ ಭುಕ್ತಿಯಲ್ಲಿ ಭೋಗ-ವೈರಾಗ್ಯ ಸಂಘರ್ಷ ಅನುಭವವಾಗುತ್ತದೆ. ವಾಹನ-ವಸ್ತ್ರ ಲಾಭ ಸಾಧ್ಯ ಆದರೆ ದಾಂಪತ್ಯದಲ್ಲಿ ಅಶಾಂತಿ ಮತ್ತು ಭಾವನಾತ್ಮಕ ಗೊಂದಲ. ಜನನೇಂದ್ರಿಯ ಸಮಸ್ಯೆ, ಚರ್ಮ ರೋಗ ಮತ್ತು ಅಲರ್ಜಿ ಸಾಧ್ಯ. ಕಲಾ ಕ್ಷೇತ್ರದಲ್ಲಿ ಅನಿರೀಕ್ಷಿತ ಯಶಸ್ಸು ಅಥವಾ ಸೋಲು.',
    'ರವಿ': 'ಕೇತು-ರವಿ ಭುಕ್ತಿಯಲ್ಲಿ ಅಧಿಕಾರ ನಷ್ಟ, ಸರ್ಕಾರಿ ತೊಂದರೆ ಮತ್ತು ತಂದೆಗೆ ಕಷ್ಟ ಬರಬಹುದು. ವೃತ್ತಿಯಲ್ಲಿ ಅನಿಶ್ಚಿತತೆ, ಸ್ಥಾನಪಲ್ಲಟ ಮತ್ತು ಅಪಕೀರ್ತಿ ಸಾಧ್ಯ. ಜ್ವರ, ಉಷ್ಣ ರೋಗ ಮತ್ತು ಅಸ್ಪಷ್ಟ ಶಿರೋವೇದನೆ. ಆಧ್ಯಾತ್ಮಿಕ ಜ್ಞಾನೋದಯ ಮತ್ತು ಸಾಧನೆಯ ಮಾರ್ಗ ತೆರೆಯಬಹುದು.',
    'ಚಂದ್ರ': 'ಕೇತು-ಚಂದ್ರ ಭುಕ್ತಿಯಲ್ಲಿ ಮಾನಸಿಕ ಅಶಾಂತಿ, ಭ್ರಮೆ ಮತ್ತು ಭಾವನಾತ್ಮಕ ಅಸ್ಥಿರತೆ ಉಂಟಾಗುತ್ತದೆ. ತಾಯಿಯ ಆರೋಗ್ಯ ಕ್ಷೀಣ, ಗೃಹ ಸುಖ ಕಡಿಮೆ ಮತ್ತು ನಿದ್ರಾ ಸಮಸ್ಯೆ. ಜಲ ಸಂಬಂಧಿ ರೋಗ, ಮಾನಸಿಕ ಒತ್ತಡ ಮತ್ತು ಅಂತರ್ಮುಖಿತನ. ಧ್ಯಾನ-ಯೋಗದಲ್ಲಿ ಆಸಕ್ತಿ ಹೆಚ್ಚಿ ಆಧ್ಯಾತ್ಮಿಕ ಬೆಳವಣಿಗೆ ಸಾಧ್ಯ.',
    'ಕುಜ': 'ಕೇತು-ಕುಜ ಭುಕ್ತಿಯಲ್ಲಿ ಅಪಘಾತ, ಶಸ್ತ್ರಚಿಕಿತ್ಸೆ ಮತ್ತು ಅಗ್ನಿ ಭಯ ಇರುತ್ತದೆ. ಶತ್ರುಗಳಿಂದ ಹಾನಿ, ಭೂಮಿ ವಿವಾದ ಮತ್ತು ವ್ಯಾಜ್ಯ ಸಾಧ್ಯ. ರಕ್ತ ದೋಷ, ಹಠಾತ್ ಗಾಯ ಮತ್ತು ಶಸ್ತ್ರ ಭಯ. ಸಹೋದರರಿಗೆ ಕಷ್ಟ, ಆದರೆ ಧೈರ್ಯ ಮತ್ತು ಸಾಹಸ ಪ್ರವೃತ್ತಿ ಹೆಚ್ಚಾಗುತ್ತದೆ.',
    'ರಾಹು': 'ಕೇತು-ರಾಹು ಭುಕ್ತಿಯಲ್ಲಿ ಅತ್ಯಂತ ಕಷ್ಟಕರ ಕಾಲ, ಮಾಯೆ-ಭ್ರಮೆಯ ಅನುಭವ ಉಂಟಾಗುತ್ತದೆ. ವೃತ್ತಿಯಲ್ಲಿ ಅನಿಶ್ಚಿತತೆ, ಮೋಸ ಮತ್ತು ಅಪಕೀರ್ತಿ ಸಾಧ್ಯ. ವಿಷ ಭಯ, ಅಸ್ಪಷ್ಟ ರೋಗ ಮತ್ತು ಮಾನಸಿಕ ಖಿನ್ನತೆ. ಕುಟುಂಬದಲ್ಲಿ ಅಶಾಂತಿ, ಆದರೆ ಆಧ್ಯಾತ್ಮಿಕ ಬೆಳವಣಿಗೆಗೆ ಅನುಕೂಲ.',
    'ಗುರು': 'ಕೇತು-ಗುರು ಭುಕ್ತಿಯಲ್ಲಿ ಆಧ್ಯಾತ್ಮಿಕ ಜ್ಞಾನ ವೃದ್ಧಿ ಮತ್ತು ಗುರು ಕೃಪೆ ಲಭಿಸುತ್ತದೆ. ಧಾರ್ಮಿಕ ಯಾತ್ರೆ, ತೀರ್ಥ ಕ್ಷೇತ್ರ ಸಂದರ್ಶನ ಮತ್ತು ಸತ್ಸಂಗ ಯೋಗ. ಆರೋಗ್ಯ ಸುಧಾರಿಸುತ್ತದೆ, ಮೋಕ್ಷ ಮಾರ್ಗದ ಆಸಕ್ತಿ ಹೆಚ್ಚುತ್ತದೆ. ಸಂತಾನ ಸುಖ ಮತ್ತು ವಿದ್ಯಾ ಲಾಭ ಸಾಧ್ಯ.',
    'ಶನಿ': 'ಕೇತು-ಶನಿ ಭುಕ್ತಿಯಲ್ಲಿ ಅತಿ ಕಠಿಣ ಕಾಲ, ದೈಹಿಕ-ಮಾನಸಿಕ ಕಷ್ಟಗಳು ಅನುಭವವಾಗುತ್ತವೆ. ವೃತ್ತಿಯಲ್ಲಿ ಸ್ಥಾನ ನಷ್ಟ, ಆರ್ಥಿಕ ಹಿಂಜರಿತ ಮತ್ತು ಹಿರಿಯರಿಂದ ಅಸಹಕಾರ. ಮೂಳೆ-ಸಂಧಿ ನೋವು, ಕಾಲು ನೋವು ಮತ್ತು ಅಸ್ಪಷ್ಟ ರೋಗ. ವೈರಾಗ್ಯ ಭಾವನೆ ಹೆಚ್ಚಿ, ಸಂನ್ಯಾಸ ಅಥವಾ ಏಕಾಂತವಾಸದ ಒಲವು.',
    'ಬುಧ': 'ಕೇತು-ಬುಧ ಭುಕ್ತಿಯಲ್ಲಿ ಬುದ್ಧಿ ಗೊಂದಲ, ಸಂವಹನ ಸಮಸ್ಯೆ ಮತ್ತು ತಪ್ಪು ಗ್ರಹಿಕೆ ಸಾಧ್ಯ. ವ್ಯಾಪಾರದಲ್ಲಿ ಮೋಸ, ಶಿಕ್ಷಣದಲ್ಲಿ ಅಡೆತಡೆ ಮತ್ತು ಲೆಕ್ಕ ಸಮಸ್ಯೆ. ನರ ರೋಗ, ಚರ್ಮ ಸಮಸ್ಯೆ ಮತ್ತು ಉಸಿರಾಟ ತೊಂದರೆ. ಆಧ್ಯಾತ್ಮಿಕ ಸಾಹಿತ್ಯ-ಅಧ್ಯಯನದಲ್ಲಿ ಆಸಕ್ತಿ ಹೆಚ್ಚಾಗಬಹುದು.',
  },
  'ಶುಕ್ರ': {
    'ಶುಕ್ರ': 'ಶುಕ್ರ ಮಹಾದಶೆಯಲ್ಲಿ ಶುಕ್ರ ಭುಕ್ತಿಯು ಅಪಾರ ಭೋಗ-ಸುಖ, ಸಂಪತ್ತು ಮತ್ತು ವೈಭವ ನೀಡುತ್ತದೆ. ವಾಹನ-ಭೂಮಿ-ಆಭರಣ ಲಾಭ, ಕಲಾ ಕ್ಷೇತ್ರದಲ್ಲಿ ಯಶಸ್ಸು ಮತ್ತು ವಿವಾಹ ಸಂಬಂಧಿ ಶುಭ ಘಟನೆಗಳು. ಆರೋಗ್ಯ ಸಾಮಾನ್ಯವಾಗಿ ಉತ್ತಮ, ಆದರೆ ಅತಿ ಭೋಗದಿಂದ ಮಧುಮೇಹ ಮತ್ತು ಕಫ ರೋಗ ಸಾಧ್ಯ. ದಾಂಪತ್ಯ ಸುಖ ಅಪಾರ, ಸಾಮಾಜಿಕ ಪ್ರತಿಷ್ಠೆ ಹೆಚ್ಚುತ್ತದೆ.',
    'ರವಿ': 'ಶುಕ್ರ-ರವಿ ಭುಕ್ತಿಯಲ್ಲಿ ಸರ್ಕಾರಿ ಅನುಕೂಲ, ಅಧಿಕಾರ ಮತ್ತು ಕೀರ್ತಿ ಲಭಿಸುತ್ತದೆ. ಕಲಾ-ಮನರಂಜನೆ ಕ್ಷೇತ್ರದಲ್ಲಿ ಸರ್ಕಾರಿ ಮಾನ್ಯತೆ ಮತ್ತು ಪ್ರಶಸ್ತಿ ಸಾಧ್ಯ. ಪಿತ್ತ-ಉಷ್ಣ ರೋಗ ಮತ್ತು ಕಣ್ಣಿನ ಸಮಸ್ಯೆ ಸಾಧ್ಯ. ತಂದೆಯೊಂದಿಗೆ ಉತ್ತಮ ಸಂಬಂಧ, ಸಾಮಾಜಿಕ ಗೌರವ ವೃದ್ಧಿ.',
    'ಚಂದ್ರ': 'ಶುಕ್ರ-ಚಂದ್ರ ಭುಕ್ತಿಯಲ್ಲಿ ಸೌಂದರ್ಯ ಪ್ರೀತಿ, ಕಲಾ ಸೃಜನಶೀಲತೆ ಮತ್ತು ಭಾವನಾತ್ಮಕ ಸಂತೃಪ್ತಿ ಲಭಿಸುತ್ತದೆ. ವಸ್ತ್ರ-ಆಭರಣ-ಸುಗಂಧ ಲಾಭ, ಸ್ತ್ರೀಯರಿಂದ ಅನುಕೂಲ ಮತ್ತು ಗೃಹ ಸುಖ. ಕಫ ರೋಗ, ಶೀತ ಸಮಸ್ಯೆ ಸಾಧ್ಯ ಆದರೆ ಒಟ್ಟಾರೆ ಆರೋಗ್ಯ ಉತ್ತಮ. ದಾಂಪತ್ಯ ಸುಖ, ತಾಯಿಯ ಆಶೀರ್ವಾದ ಮತ್ತು ಕುಟುಂಬ ಸಾಮರಸ್ಯ.',
    'ಕುಜ': 'ಶುಕ್ರ-ಕುಜ ಭುಕ್ತಿಯಲ್ಲಿ ಭೂಮಿ-ವಾಹನ ಲಾಭ ಮತ್ತು ಭೋಗ ಸುಖ ಲಭಿಸುತ್ತದೆ. ಆದರೆ ದಾಂಪತ್ಯದಲ್ಲಿ ಕಲಹ, ಅತಿ ಕಾಮ ವಾಂಛೆ ಮತ್ತು ಭಾವನಾತ್ಮಕ ಸಂಘರ್ಷ ಸಾಧ್ಯ. ಜನನೇಂದ್ರಿಯ ಸಮಸ್ಯೆ, ರಕ್ತ ದೋಷ ಮತ್ತು ಚರ್ಮ ರೋಗ. ಆಸ್ತಿ ವಿವಾದ ಇರಬಹುದು, ಸ್ಪರ್ಧೆಗಳಲ್ಲಿ ಜಯ ಸಾಧ್ಯ.',
    'ರಾಹು': 'ಶುಕ್ರ-ರಾಹು ಭುಕ್ತಿಯಲ್ಲಿ ವಿದೇಶ ಸಂಬಂಧ, ಅಂತರ್ಜಾತೀಯ ವಿವಾಹ ಮತ್ತು ಅನಿರೀಕ್ಷಿತ ಸಂಪತ್ತು ಸಾಧ್ಯ. ಭೋಗ-ವಿಲಾಸದಲ್ಲಿ ಅತಿರೇಕ, ಮೋಸ ಮತ್ತು ಅನೈತಿಕ ಸಂಬಂಧಗಳ ಭಯ. ಜನನೇಂದ್ರಿಯ ರೋಗ, ವಿಷ ಭಯ ಮತ್ತು ಚರ್ಮ ಸಮಸ್ಯೆ. ದಾಂಪತ್ಯದಲ್ಲಿ ಗೊಂದಲ, ಆದರೆ ಐಷಾರಾಮಿ ವಸ್ತುಗಳ ಲಾಭ.',
    'ಗುರು': 'ಶುಕ್ರ-ಗುರು ಭುಕ್ತಿಯಲ್ಲಿ ಶ್ರೇಷ್ಠ ಫಲ, ಸಂಪತ್ತು-ಸುಖ-ಗೌರವ ಲಭಿಸುತ್ತದೆ. ವಿವಾಹ ಯೋಗ, ಸಂತಾನ ಸುಖ, ಧಾರ್ಮಿಕ ಕಾರ್ಯ ಮತ್ತು ಕಲಾ-ಸಂಸ್ಕೃತಿಯಲ್ಲಿ ಉನ್ನತಿ. ಆರೋಗ್ಯ ಉತ್ತಮ, ಕೊಬ್ಬು ವೃದ್ಧಿ ಸಾಧ್ಯ. ಗುರು ಕೃಪೆ, ಸಾಮಾಜಿಕ ಪ್ರತಿಷ್ಠೆ ಮತ್ತು ಧರ್ಮ-ಕರ್ಮಗಳಲ್ಲಿ ಪ್ರಗತಿ.',
    'ಶನಿ': 'ಶುಕ್ರ-ಶನಿ ಭುಕ್ತಿಯಲ್ಲಿ ಐಷಾರಾಮ ವಸ್ತುಗಳ ಲಾಭ ಮತ್ತು ಸ್ಥಿರ ಸಂಪತ್ತು ಲಭಿಸಬಹುದು. ಆದರೆ ದಾಂಪತ್ಯದಲ್ಲಿ ಶೀತಲತೆ, ಭಾವನಾತ್ಮಕ ದೂರ ಮತ್ತು ವಿಳಂಬ ಸಾಧ್ಯ. ಮಧುಮೇಹ, ಜನನೇಂದ್ರಿಯ ಸಮಸ್ಯೆ ಮತ್ತು ವಾತ ರೋಗ. ಕಲಾ ಕ್ಷೇತ್ರದಲ್ಲಿ ಕಠಿಣ ಪರಿಶ್ರಮದ ನಂತರ ಯಶಸ್ಸು.',
    'ಬುಧ': 'ಶುಕ್ರ-ಬುಧ ಭುಕ್ತಿಯಲ್ಲಿ ವ್ಯಾಪಾರ-ಕಲೆ-ಸಂಗೀತದಲ್ಲಿ ಲಾಭ ಮತ್ತು ಸಂವಹನ ಕೌಶಲ ಹೆಚ್ಚುತ್ತದೆ. ಬರವಣಿಗೆ, ಮಾಧ್ಯಮ ಮತ್ತು ಸೌಂದರ್ಯ ಉದ್ಯಮದಲ್ಲಿ ಪ್ರಗತಿ ಸಾಧ್ಯ. ಚರ್ಮ ರೋಗ, ಅಲರ್ಜಿ ಸಾಧ್ಯ ಆದರೆ ಒಟ್ಟಾರೆ ಆರೋಗ್ಯ ಉತ್ತಮ. ಮಿತ್ರ-ಬಂಧು ಸಹಕಾರ ಮತ್ತು ಸಾಮಾಜಿಕ ಜೀವನದಲ್ಲಿ ಆನಂದ.',
    'ಕೇತು': 'ಶುಕ್ರ-ಕೇತು ಭುಕ್ತಿಯಲ್ಲಿ ಭೋಗ-ವಿಲಾಸದಲ್ಲಿ ಅಡ್ಡಿ ಮತ್ತು ವೈರಾಗ್ಯ ಭಾವನೆ ಬರುತ್ತದೆ. ವಾಹನ ನಷ್ಟ, ಆಭರಣ ಕಳೆದುಹೋಗುವುದು ಮತ್ತು ಸಂಪತ್ತಿನ ಹಠಾತ್ ನಷ್ಟ ಸಾಧ್ಯ. ಜನನೇಂದ್ರಿಯ ಸಮಸ್ಯೆ, ಅಸ್ಪಷ್ಟ ರೋಗ ಮತ್ತು ಅಲರ್ಜಿ. ದಾಂಪತ್ಯದಲ್ಲಿ ಅಶಾಂತಿ, ಆದರೆ ಆಧ್ಯಾತ್ಮಿಕ ಒಲವು ಹೆಚ್ಚಾಗುತ್ತದೆ.',
  },
};
